-- REG-01 · Compliance › Regulatory watch (roadmap item 3, 30/10). Model = Monday « Regulation monitoring 2.0 », simplified:
-- topics (one watch stream, an owner, a cadence, a last-check date) → sources (what to open) → checks (the proof: who looked, when,
-- nothing new / entries raised) → entries (a text that may concern us: applicability, impact, owner, due, what we did, closed).
create table if not exists watch_topics (
  id uuid primary key default gen_random_uuid(),
  key text unique,
  title text not null,
  domain text not null default 'compliance' check (domain in ('compliance','safety','ato_fstd','manufacturer')),
  entities entity_code[] not null default '{}',
  owner_role text,
  owner_person uuid references people(id) on delete set null,
  every_days int not null default 30,
  last_checked_on date,
  last_checked_by uuid references people(id) on delete set null,
  active boolean not null default true,
  created_at timestamptz not null default now()
);
create table if not exists watch_sources (
  id uuid primary key default gen_random_uuid(),
  topic_id uuid not null references watch_topics(id) on delete cascade,
  name text not null,
  kind text not null default 'misc' check (kind in ('easa','dsac','osac','tmcad','jorf','bea','manufacturer','icao','misc')),
  url text,
  domain text,                                    -- CAMO · OPS · ATO · FSTD · All
  note text,
  active boolean not null default true,
  last_checked_on date,
  last_checked_by uuid references people(id) on delete set null,
  last_result text,                               -- nothing_new | entries
  created_at timestamptz not null default now()
);
create table if not exists watch_checks (
  id uuid primary key default gen_random_uuid(),
  topic_id uuid not null references watch_topics(id) on delete cascade,
  source_id uuid references watch_sources(id) on delete set null,
  checked_on date not null default current_date,
  checked_by uuid references people(id) on delete set null,
  result text not null default 'nothing_new' check (result in ('nothing_new','entries','not_reachable')),
  note text,
  created_at timestamptz not null default now()
);
create index if not exists watch_checks_topic on watch_checks (topic_id, checked_on desc);
create table if not exists watch_entries (
  id uuid primary key default gen_random_uuid(),
  key text unique,                                -- import key
  number text not null,                           -- REG-ASJMT-2026-001
  entity entity_code not null references entities(code),
  topic_id uuid references watch_topics(id) on delete set null,
  source_id uuid references watch_sources(id) on delete set null,
  check_id uuid references watch_checks(id) on delete set null,
  source_kind text,
  domain text,
  title text not null,
  reference text,                                 -- ED Decision 2026/006/R, ORO.FC.230, AD 2026-0125R1…
  url text,
  published_on date,
  applicable_on date,
  applicability text not null default 'to_analyse' check (applicability in ('to_analyse','applicable','for_information','not_applicable')),
  task text check (task in ('study','apply')),    -- what the owner is asked to do
  impact text,                                    -- manuals / procedures / training concerned, as analysed
  manual_ids uuid[] not null default '{}',
  revision_ids uuid[] not null default '{}',      -- drafts opened to address it
  owner_role text,
  owner_person uuid references people(id) on delete set null,
  due date,                                       -- to return before
  status text not null default 'open' check (status in ('open','in_progress','done','closed','not_applicable')),
  conclusion text,                                -- what was done / why nothing was needed
  assistant jsonb,                                -- S.A.M.'s reading: {"applicability","summary","chapters":[{manual,ref,why}],"task","model","at"}
  closed_at timestamptz, closed_by uuid references people(id) on delete set null,
  imported_from text,
  created_by uuid references people(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (entity, number)
);
create index if not exists watch_entries_scope on watch_entries (entity, status);
alter table safety_actions add column if not exists watch_entry_id uuid references watch_entries(id) on delete set null;
alter table watch_topics enable row level security; alter table watch_sources enable row level security; alter table watch_checks enable row level security; alter table watch_entries enable row level security;
drop policy if exists watch_topics_read on watch_topics; create policy watch_topics_read on watch_topics for select using (true);
drop policy if exists watch_sources_read on watch_sources; create policy watch_sources_read on watch_sources for select using (true);
drop policy if exists watch_checks_read on watch_checks; create policy watch_checks_read on watch_checks for select using (true);
drop policy if exists watch_entries_read on watch_entries; create policy watch_entries_read on watch_entries for select using (true);
on conflict (kind) do nothing;

-- REG-01 seed · topics and sources from Monday « Regulation monitoring 2.0 » (18392092988), sources + history from « Regulation monitoring – ASTONFLY ATO/FSTD » (18430950291). Mirror of the sources, 30/10/2026.
